create table payment (fee_rate_basis_points integer not null, approved_at timestamp(6) with time zone, fee bigint not null, franchise_id bigint not null, payment_id bigint generated by default as identity, payout bigint not null, request_membership_id bigint not null, request_price bigint not null, requested_at timestamp(6) with time zone not null, settled_at timestamp(6) with time zone, request_id varchar(64) not null unique, payment_status varchar(255) not null check ((payment_status in ('REQUESTED','PAID','FAILED','SETTLED'))), primary key (payment_id), constraint payment_price_positive check (request_price > 0), constraint payment_fee_rate_in_range check (fee_rate_basis_points BETWEEN 0 AND 10000), constraint payment_fee_and_payout_make_the_price check (fee >= 0 AND payout >= 0 AND fee + payout = request_price));
insert into payment (fee_rate_basis_points, fee, franchise_id, payout, request_membership_id, request_price, requested_at, request_id, payment_status) values (100, 10, 1, 990, 1, 1000, now(), 'upgrade-1', 'PAID');
